import unittest

class Contract(unittest.TestCase):
    def test_early(self):
        from config import migrate
        data = {"host": "old", "endpoint": "new", "retries": 0, "timeout": 0, "extension": 7}
        before = dict(data)
        result = migrate(data)
        self.assertEqual(result, before)
        self.assertEqual(data, before)
        self.assertEqual(migrate({"host": "old"})["endpoint"], "old")
    def test_middle(self):
        from client import request_options
        for data in ({"host": ""}, {"host": "ok", "retries": True}, {"host": "ok", "retries": -1}, {"host": "ok", "timeout": -1}, {"host": "ok", "timeout": False}):
            with self.assertRaises(ValueError):
                request_options(data)
    def test_final(self):
        from client import connect
        self.assertEqual(connect({"host": "old", "retries": 0, "timeout": 0}), {"url": "old", "attempts": 1, "timeout": 0})
        self.assertEqual(connect({"endpoint": "new"}), {"url": "new", "attempts": 4, "timeout": 5})

