from config import migrate

def request_options(data):
    result = migrate(data)
    if not isinstance(result["endpoint"], str) or not result["endpoint"]:
        raise ValueError("endpoint")
    if type(result["retries"]) is not int or result["retries"] < 0:
        raise ValueError("retries")
    if type(result["timeout"]) not in (int, float) or result["timeout"] < 0:
        raise ValueError("timeout")
    return result

def connect(data):
    options = request_options(data)
    return {"url": options["endpoint"], "attempts": options["retries"] + 1, "timeout": options["timeout"]}
